// activity_resources rows are cheap to fully rebuild rather than diff —
// this is a create, so there's nothing to diff against yet.
const inserted = $json; // { id, subject, due_at, created_at }
const activityId = parseInt(inserted.id, 10);
const resourceIds = ($('Webhook: add-event').first().json.body.resource_ids || [])
  .map((x) => parseInt(x, 10))
  .filter((x) => Number.isInteger(x));

const sqlQuery = resourceIds.length > 0
  ? `INSERT INTO activity_resources (activity_id, resource_id) VALUES ${resourceIds.map((rid) => `(${activityId}, ${rid})`).join(', ')} ON CONFLICT DO NOTHING;`
  : 'SELECT 1;';

return [{ json: { ...inserted, sqlQuery } }];

