// Only touch activity_resources if the caller explicitly sent a
// resource_ids field — an update that doesn't mention resources shouldn't
// wipe out the ones already linked.
const updated = $json; // { id }
const body = $('Webhook: update-event').first().json.body || {};
const activityId = parseInt(updated.id, 10);

if (!Number.isInteger(activityId) || !Object.prototype.hasOwnProperty.call(body, 'resource_ids')) {
  return [{ json: { ...updated, sqlQuery: 'SELECT 1;' } }];
}

const resourceIds = (body.resource_ids || [])
  .map((x) => parseInt(x, 10))
  .filter((x) => Number.isInteger(x));

const insertClause = resourceIds.length > 0
  ? ` INSERT INTO activity_resources (activity_id, resource_id) VALUES ${resourceIds.map((rid) => `(${activityId}, ${rid})`).join(', ')} ON CONFLICT DO NOTHING;`
  : '';

const sqlQuery = `DELETE FROM activity_resources WHERE activity_id = ${activityId};${insertClause}`;

return [{ json: { ...updated, sqlQuery } }];

const result = $input.first();
if (!result || !result.json || !result.json.id) {
  throw new Error("Event not found or you do not have permission to edit it.");
}
return [{ json: { success: true, ...result.json } }];

const conflict = $input.first().json;
if (conflict && conflict.id) {
  const when = new Date(conflict.due_at).toLocaleString();
  throw new Error(`This time conflicts with an existing event: "${conflict.subject}" at ${when}. Choose a different time or remove the conflicting event first.`);
}
return [{ json: { ok: true } }];

