const target = $input.first().json;
const event = $('Postgres: Insert Event').first().json;

const body = {
  summary: event.subject || 'CRM Event',
  start: { dateTime: event.due_at },
  end: { dateTime: event.end_at || event.due_at },
};
if (event.body) body.description = event.body;
if (target.contact_email) {
  body.attendees = [{ email: target.contact_email, displayName: target.contact_name || undefined }];
}

return [{
  json: {
    activityId: event.id,
    url: `https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(target.calendar_id)}/events`,
    bodyJson: JSON.stringify(body),
  },
}];

const target = $input.first().json;
const event = $('Postgres: Update Event').first().json;

const body = {
  summary: event.subject || 'CRM Event',
  start: { dateTime: event.due_at },
  end: { dateTime: event.end_at || event.due_at },
};
if (event.body) body.description = event.body;
if (target.contact_email) {
  body.attendees = [{ email: target.contact_email, displayName: target.contact_name || undefined }];
}

const hasExisting = !!event.google_event_id;
const url = hasExisting
  ? `https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(target.calendar_id)}/events/${encodeURIComponent(event.google_event_id)}`
  : `https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(target.calendar_id)}/events`;

return [{
  json: {
    activityId: event.id,
    hasExisting,
    url,
    bodyJson: JSON.stringify(body),
  },
}];

const headers = $('Webhook: update-event').first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
if (!token) throw new Error('Invalid or missing session token.');
return [{ json: { token } }];

const r = $input.first().json;
if (!r.valid) throw new Error('Invalid session.');

return [{ json: { id: r.userId, role: r.role, name: r.user?.name, active: r.active } }];

